import styled from '@emotion/styled';

import { theme } from '../../theme';

export const SegmentedControlRoot = styled.div({
  display: 'inline-flex',
  alignItems: 'stretch',
  borderRadius: '999px',
  background: '#1414140a',
  maxWidth: 'fit-content',
});

export const SegmentedControlItem = styled.button<{ $isSelected: boolean }>(
  ({ $isSelected }) => ({
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '8px',
    minHeight: '40px',
    padding: '12px 18px',
    border: $isSelected ? `1px solid ${theme.colors.border.default}` : 'none',
    borderRadius: '999px',
    background: $isSelected ? theme.colors.neutral0 : 'transparent',
    color: $isSelected ? theme.colors.txt.default : theme.colors.txt.secondary,
    cursor: 'pointer',
    fontSize: '14px',
    fontWeight: $isSelected ? 600 : 500,
    lineHeight: '20px',

    boxShadow: $isSelected
      ? `0 1px 3px ${theme.colors.border.default}`
      : 'none',

    '&:hover:not(:disabled)': {
      color: theme.colors.txt.default,
    },

    '&:focus-visible': {
      outline: `2px solid ${theme.colors.semanticInfoText}`,
      outlineOffset: '2px',
    },
    '&:disabled': {
      cursor: 'not-allowed',
      opacity: 0.5,
    },
  }),
);

export const SegmentedControlLabel = styled.span({
  display: 'inline-flex',
  alignItems: 'center',
  gap: '8px',
  whiteSpace: 'nowrap',
});

export const SegmentedControlImage = styled.img<{ $isSelected: boolean }>(
  ({ $isSelected }) => ({
    width: '15px',
    height: '15px',
    objectFit: 'cover',
    flexShrink: 0,
    filter: $isSelected ? 'none' : 'grayscale(100%) opacity(0.36)',
    transition: 'filter 0.2s ease',
  }),
);

export const SegmentedControlImageSlot = styled.span<{ $isSelected: boolean }>(
  ({ $isSelected }) => ({
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    width: '20px',
    height: '20px',
    flexShrink: 0,
    color: $isSelected
      ? theme.colors.txt.default
      : theme.colors.interfaceLabelSecondary,
    transition: 'color 0.2s ease',

    '& svg': {
      width: '15px',
      height: '15px',
      color: 'inherit',
      flexShrink: 0,
    },

    'button:hover:not(:disabled) &': {
      color: theme.colors.txt.default,
    },
  }),
);
